message.content:
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?company ?label ?num WHERE {
  ?company a iof-core:Manufacturer ;
           rdfs:label ?label ;
           sdk:hasNumberOfEmployees ?num .
  FILTER(CONTAINS(LCASE(STR(?label)), "steel"))
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?name WHERE {
  ?m a iof-core:Manufacturer ;
     sdk:hasCertificate ?cert ;
     rdfs:label ?name .
  ?cert rdfs:label "ISO 9001" .
  FILTER(langMatches(lang(?name),"en") || lang(?name) = "")
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?naicsText WHERE {
  ?naics sdk:hasNAICSCodeValue ?code ;
         sdk:hasNAICSTextValue ?naicsText .
  FILTER(CONTAINS(str(?code), "332996"))
}
LIMIT 1

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX iof-scro: <https://spec.industrialontologies.org/ontology/supplychain/SupplyChain/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX bfo: <http://purl.obolibrary.org/obo/>

SELECT ?naics ?code WHERE {
  ?naics a sdk:NAICS332996.0 ;
         sdk:hasNAICSTextValue ?text ;
         sdk:hasNAICSCodeValue ?code .
  FILTER(CONTAINS(UCASE(STR(?text)), "PIPE AND PIPE FITTING"))
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX iof-scro: <https://spec.industrialontologies.org/ontology/supplychain/SupplyChain/>

SELECT ?businessDescriptionText WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?name ;
                iof-core:describedBy ?desc .
  ?desc a sdk:BusinessDescription ;
        iof-scro:hasTextValue ?businessDescriptionText .
  FILTER(CONTAINS(LCASE(STR(?name)), "fabrication"))
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-scro: <https://spec.industrialontologies.org/ontology/supplychain/SupplyChain/>

SELECT ?zipCode WHERE {
  ?site a sdk:GeospatialLocation ;
        sdk:hasPostalAddress ?addr ;
        sdk:hasZIPcode ?zip .
  ?addr iof-scro:hasTextValue ?addrText .
  ?zip sdk:hasIntegerValue ?zipCode .
  FILTER(CONTAINS(LCASE(str(?addrText)), "suite"))
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?stateLabel WHERE {
  ?city a sdk:City ;
        rdfs:label ?cityLabel ;
        sdk:locatedInState ?state .
  ?state rdfs:label ?stateLabel .
  FILTER(CONTAINS(STR(?cityLabel), "San "))
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?name ?naicsCode WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?name ;
                sdk:hasPrimaryNAICSClassifier ?naicsInst .
  ?naicsInst sdk:hasNAICSCodeValue ?naicsCode .
  FILTER(CONTAINS(LCASE(STR(?name)), "precision"))
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?industry ?industryLabel WHERE {
  ?man a iof-core:Manufacturer ;
       rdfs:label ?name ;
       sdk:suppliesToIndustry ?industry .
  ?industry rdfs:label ?industryLabel .
  FILTER(CONTAINS(LCASE(STR(?name)), "automation"))
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?product ?productLabel WHERE {
  ?company a iof-core:Manufacturer ;
           rdfs:label ?companyName ;
           sdk:manufactures ?product .
  FILTER(regex(str(?companyName), "Tooling", "i")) .
  OPTIONAL { ?product rdfs:label ?productLabel . }
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?company ?companyLabel ?processCapability ?processCapabilityLabel WHERE {
  ?company a iof-core:Manufacturer ;
           rdfs:label ?companyLabel ;
           sdk:hasProcessCapability ?processCapability .
  FILTER(CONTAINS(LCASE(STR(?companyLabel)), "aerospace"))
  OPTIONAL { ?processCapability rdfs:label ?processCapabilityLabel }
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?company ?companyLabel ?matCap ?matCapLabel WHERE {
  ?company a iof-core:Manufacturer ;
           rdfs:label ?companyLabel ;
           sdk:hasMaterialCapability ?matCap .
  ?matCap rdfs:label ?matCapLabel .
  FILTER(CONTAINS(LCASE(STR(?companyLabel)), "metal"))
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?manufacturerLabel ?cert ?certLabel ?certType WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?manufacturerLabel ;
                sdk:hasCertificate ?cert .
  FILTER(CONTAINS(LCASE(STR(?manufacturerLabel)), "plastics"))
  OPTIONAL { ?cert rdfs:label ?certLabel. }
  OPTIONAL { ?cert a ?certType. }
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?company ?companyLabel ?city ?cityLabel WHERE {
  ?company a iof-core:Manufacturer ;
           rdfs:label ?companyLabel ;
           sdk:organizationLocatedIn ?site .
  ?site sdk:locatedInCity ?city .
  ?city rdfs:label ?cityLabel .
  FILTER(CONTAINS(LCASE(?companyLabel), "robotics"))
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?manufacturerName ?state ?stateName WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?manufacturerName ;
                sdk:organizationLocatedIn ?site .
  ?site sdk:locatedInCity ?city .
  ?city sdk:locatedInState ?state .
  ?state rdfs:label ?stateName .
  FILTER(CONTAINS(LCASE(?manufacturerName), "valve"))
} ORDER BY ?manufacturerName

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?zipValue WHERE {
  ?company a iof-core:Manufacturer ;
           rdfs:label ?label ;
           sdk:organizationLocatedIn ?site .
  FILTER(CONTAINS(LCASE(?label), "casting"))
  ?site sdk:hasZIPcode ?zip .
  ?zip sdk:hasIntegerValue ?zipValue .
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?state (COALESCE(?stateLabel, STR(?state)) AS ?stateName) (COUNT(DISTINCT ?manufacturer) AS ?manufacturerCount)
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:organizationLocatedIn ?site .
  ?site sdk:locatedInCity ?city .
  ?city sdk:locatedInState ?state .
  OPTIONAL { ?state rdfs:label ?stateLabel }
}
GROUP BY ?state ?stateLabel
ORDER BY DESC(?manufacturerCount)

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?city ?cityLabel (COUNT(DISTINCT ?manufacturer) AS ?manufacturerCount)
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:organizationLocatedIn ?site .
  ?site sdk:locatedInCity ?city .
  OPTIONAL { ?city rdfs:label ?cityLabel . }
}
GROUP BY ?city ?cityLabel
ORDER BY DESC(?manufacturerCount)

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?cert ?certLabel (COUNT(DISTINCT ?manufacturer) AS ?manufacturerCount)
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:hasCertificate ?cert .
  OPTIONAL { ?cert rdfs:label ?certLabel . }
}
GROUP BY ?cert ?certLabel
ORDER BY DESC(?manufacturerCount)

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?naics ?naicsCode ?naicsText (COUNT(?manufacturer) AS ?numManufacturers)
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:hasPrimaryNAICSClassifier ?naics .
  ?naics sdk:hasNAICSCodeValue ?naicsCode ;
         sdk:hasNAICSTextValue ?naicsText .
}
GROUP BY ?naics ?naicsCode ?naicsText
ORDER BY DESC(?numManufacturers)

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?label (COUNT(DISTINCT ?product) AS ?productCount)
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:manufactures ?product .
  OPTIONAL { ?manufacturer rdfs:label ?label }
}
GROUP BY ?manufacturer ?label
ORDER BY DESC(?productCount)

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?label (COUNT(DISTINCT ?cap) AS ?totalCapabilities)
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL { ?manufacturer rdfs:label ?label }
  OPTIONAL { ?manufacturer (sdk:hasProcessCapability|sdk:hasMaterialCapability) ?cap }
}
GROUP BY ?manufacturer ?label
ORDER BY DESC(?totalCapabilities)

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?cert WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:hasCertificate ?cert .
  ?cert rdfs:label "ISO 9001" .
}
LIMIT 1

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?label ?naics ?naicsCode ?naicsText
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?label .
  FILTER(CONTAINS(LCASE(STR(?label)), "pipe"))
  OPTIONAL {
    ?manufacturer sdk:hasPrimaryNAICSClassifier ?naics .
    OPTIONAL { ?naics sdk:hasNAICSCodeValue ?naicsCode . }
    OPTIONAL { ?naics sdk:hasNAICSTextValue ?naicsText . }
  }
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

ASK {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:manufactures ?product .
  ?product rdfs:label ?productLabel .
  FILTER(CONTAINS(LCASE(STR(?productLabel)), "valve"))
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

ASK WHERE {
  ?org a iof-core:Manufacturer ;
       sdk:organizationLocatedIn ?site .
  ?site sdk:locatedInCity ?city .
  ?city rdfs:label ?cityLabel ;
        sdk:locatedInState ?state .
  ?state rdfs:label ?stateLabel .
  FILTER(STR(?cityLabel) = "Phoenix" && STR(?stateLabel) = "Arizona")
  FILTER NOT EXISTS { ?org sdk:hasCertificate ?cert }
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>

ASK {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:organizationLocatedIn ?site .
  ?site sdk:hasSpatialCoordinates ?coords .
  ?coords sdk:hasLatitudeValue ?lat ;
          sdk:hasLongitudeValue ?long .
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

ASK WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:hasMaterialCapability ?matBronze , ?matSteel .
  ?matBronze a sdk:BronzeProcessingCapability .
  ?matSteel a sdk:SteelProcessingCapability .
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?label
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  FILTER NOT EXISTS { ?manufacturer sdk:hasCertificate ?cert . }
  OPTIONAL { ?manufacturer rdfs:label ?label . }
}
LIMIT 1

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX iof-scro: <https://spec.industrialontologies.org/ontology/supplychain/SupplyChain/>

SELECT ?manufacturer ?label ?hasBusinessDescription ?descriptionText
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?label .
  FILTER(CONTAINS(LCASE(?label), "coating"))
  OPTIONAL {
    ?manufacturer iof-core:describedBy ?desc .
    ?desc a sdk:BusinessDescription .
    OPTIONAL { ?desc iof-scro:hasTextValue ?descriptionText }
  }
  BIND(BOUND(?desc) AS ?hasBusinessDescription)
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?manufacturer ?label ?employeesInt WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?label ;
                sdk:hasNumberOfEmployees ?employees .
  BIND(xsd:integer(REPLACE(STR(?employees), ",", "")) AS ?employeesInt)
  FILTER(?employeesInt > 500)
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?label
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?label .
  FILTER regex(?label, "^A")
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?naics ?text WHERE {
  ?naics sdk:hasNAICSTextValue ?text .
  FILTER(CONTAINS(LCASE(STR(?text)), "pipe"))
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT DISTINCT ?manufacturer ?label WHERE {
  ?manufacturer rdf:type iof-core:Manufacturer ;
                rdfs:label ?label ;
                sdk:organizationLocatedIn ?site .
  ?site sdk:hasZIPcode ?zip .
  ?zip sdk:hasIntegerValue "85027.0"^^xsd:string .
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?manufacturer ?label ?latitude
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?label ;
                sdk:organizationLocatedIn ?site .
  ?site sdk:hasSpatialCoordinates ?coords .
  ?coords sdk:hasLatitudeValue ?latitude .
  FILTER(xsd:float(?latitude) > 45.0)
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?manufacturer ?label ?longitude WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?label ;
                sdk:organizationLocatedIn ?site .
  ?site sdk:hasSpatialCoordinates ?coords .
  ?coords sdk:hasLongitudeValue ?longitude .
  FILTER(xsd:float(?longitude) < 100.0)
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?manufacturerLabel ?industry ?industryLabel WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?manufacturerLabel ;
                sdk:suppliesToIndustry ?industry .
  ?industry rdfs:label ?industryLabel .
  FILTER(regex(?industryLabel, "Utilities", "i"))
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?product ?productLabel ?manufacturer ?manufacturerLabel
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:manufactures ?product ;
                rdfs:label ?manufacturerLabel .
  ?product a iof-core:MaterialProduct ;
           rdfs:label ?productLabel .
}
ORDER BY ?productLabel ?manufacturerLabel

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?name
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?name .
  FILTER(STRLEN(STR(?name)) > 8)
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?manufacturer ?label ?num WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:hasNumberOfEmployees ?numLit .
  OPTIONAL { ?manufacturer rdfs:label ?label. }
  BIND(xsd:integer(REPLACE(str(?numLit), ",", "")) AS ?num)
}
ORDER BY DESC(?num)
LIMIT 1

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?city ?cityLabel (COUNT(DISTINCT ?m) AS ?numManufacturers)
WHERE {
  ?m a iof-core:Manufacturer ;
     sdk:organizationLocatedIn ?site .
  ?site sdk:locatedInCity ?city .
  OPTIONAL { ?city rdfs:label ?cityLabel . }
}
GROUP BY ?city ?cityLabel
ORDER BY DESC(?numManufacturers)
LIMIT 1

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?industry ?industryLabel (COUNT(DISTINCT ?manufacturer) AS ?numSuppliers)
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:suppliesToIndustry ?industry .
  OPTIONAL { ?industry rdfs:label ?industryLabel . }
}
GROUP BY ?industry ?industryLabel
ORDER BY DESC(?numSuppliers)
LIMIT 1

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?certificate ?label (COUNT(DISTINCT ?manufacturer) AS ?numManufacturers)
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:hasCertificate ?certificate .
  OPTIONAL { ?certificate rdfs:label ?label. }
}
GROUP BY ?certificate ?label
ORDER BY DESC(?numManufacturers)
LIMIT 1

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?product ?productLabel (COUNT(DISTINCT ?manufacturer) AS ?numManufacturers)
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:manufactures ?product .
  ?product a iof-core:MaterialProduct .
  OPTIONAL { ?product rdfs:label ?productLabel. }
}
GROUP BY ?product ?productLabel
ORDER BY DESC(?numManufacturers)
LIMIT 1

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?label (COUNT(DISTINCT ?cap) AS ?capCount)
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL { ?manufacturer rdfs:label ?label . }
  {
    ?manufacturer sdk:hasProcessCapability ?cap .
  } UNION {
    ?manufacturer sdk:hasMaterialCapability ?cap .
  }
}
GROUP BY ?manufacturer ?label
ORDER BY DESC(?capCount)
LIMIT 1

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-scro: <https://spec.industrialontologies.org/ontology/supplychain/SupplyChain/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?naics ?code ?text (COUNT(DISTINCT ?man) AS ?numManufacturers)
WHERE {
  ?man a iof-core:Manufacturer ;
       sdk:hasPrimaryNAICSClassifier ?naics .
  OPTIONAL { ?naics sdk:hasNAICSCodeValue ?code. }
  OPTIONAL { ?naics sdk:hasNAICSTextValue ?text. }
}
GROUP BY ?naics ?code ?text
ORDER BY DESC(?numManufacturers)
LIMIT 1

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?manufacturerLabel ?naicsText
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL {
    ?manufacturer sdk:hasPrimaryNAICSClassifier ?naics .
    ?naics sdk:hasNAICSTextValue ?naicsText .
  }
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel . }
}
ORDER BY ?manufacturerLabel

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?manufacturerLabel WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:hasProcessCapability ?cap .
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel }
  ?cap rdfs:label ?capLabel .
  FILTER( ?capLabel = "Machining" || ?capLabel = "Coating" )
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?manufacturerLabel (GROUP_CONCAT(DISTINCT ?capLabel; SEPARATOR=", ") AS ?capabilities)
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel. }
  OPTIONAL {
    { ?manufacturer sdk:hasProcessCapability ?cap. }
    UNION
    { ?manufacturer sdk:hasMaterialCapability ?cap. }
    ?cap rdfs:label ?capLabel.
  }
}
GROUP BY ?manufacturer ?manufacturerLabel
ORDER BY ?manufacturerLabel

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?manufacturerName ?cityName ?stateName WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerName. }

  OPTIONAL {
    ?manufacturer sdk:organizationLocatedIn ?site .

    OPTIONAL {
      ?site sdk:locatedInCity ?city .
      OPTIONAL { ?city rdfs:label ?cityName. }
      OPTIONAL {
        ?city sdk:locatedInState ?stateFromCity .
        OPTIONAL { ?stateFromCity rdfs:label ?stateFromCityLabel. }
      }
    }

    OPTIONAL {
      ?site sdk:locatedInState ?stateDirect .
      OPTIONAL { ?stateDirect rdfs:label ?stateDirectLabel. }
    }
  }

  BIND(COALESCE(?stateFromCityLabel, ?stateDirectLabel) AS ?stateName)
} ORDER BY ?manufacturerName

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?manufacturerLabel WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:suppliesToIndustry ?industry .
  ?industry a ?industryType .
  VALUES ?industryType { sdk:RenewableEnergyIndustry sdk:UtilitiesIndustry }
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel }
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?manufacturerLabel (GROUP_CONCAT(DISTINCT ?itemLabelFinal; separator=", ") AS ?items)
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel . }
  OPTIONAL {
    { ?manufacturer sdk:manufactures ?item }
    UNION
    { ?manufacturer sdk:hasCertificate ?item }
    OPTIONAL { ?item rdfs:label ?itemLabel }
    BIND(COALESCE(?itemLabel, STR(?item)) AS ?itemLabelFinal)
  }
}
GROUP BY ?manufacturer ?manufacturerLabel
ORDER BY ?manufacturerLabel

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?manufacturerLabel ?latitude ?longitude
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel. }
  OPTIONAL {
    ?manufacturer sdk:organizationLocatedIn ?site .
    OPTIONAL {
      ?site sdk:hasSpatialCoordinates ?coords .
      OPTIONAL { ?coords sdk:hasLatitudeValue ?latitude. }
      OPTIONAL { ?coords sdk:hasLongitudeValue ?longitude. }
    }
  }
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX iof-scro: <https://spec.industrialontologies.org/ontology/supplychain/SupplyChain/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer (COALESCE(?descText, ?name) AS ?businessDescription)
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL {
    ?manufacturer iof-core:describedBy ?desc .
    ?desc iof-scro:hasTextValue ?descText .
  }
  OPTIONAL { ?manufacturer rdfs:label ?name . }
}
ORDER BY ?manufacturer

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?manufacturerLabel ?cityLabel WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:organizationLocatedIn ?site .
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel. }
  ?site sdk:locatedInCity ?city .
  ?city rdfs:label ?cityLabel .
  FILTER(CONTAINS(LCASE(STR(?cityLabel)), LCASE("Rochester")))
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?manufacturerLabel ?site ?cityLabel ?stateLabel WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?manufacturerLabel ;
                sdk:organizationLocatedIn ?site .
  ?site a sdk:GeospatialLocation ;
        sdk:locatedInCity ?city .
  ?city a sdk:City ;
        rdfs:label ?cityLabel ;
        sdk:locatedInState ?state .
  ?state a sdk:State ;
         rdfs:label ?stateLabel .
  FILTER(str(?stateLabel) = "California")
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?city ?cityLabel (COUNT(DISTINCT ?manufacturer) AS ?manufacturerCount)
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:organizationLocatedIn ?site .
  ?site sdk:locatedInCity ?city .
  OPTIONAL { ?city rdfs:label ?cityLabel . }
}
GROUP BY ?city ?cityLabel
ORDER BY DESC(?manufacturerCount)

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?manufacturer ?label ?lat WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?label ;
                sdk:organizationLocatedIn ?site .
  ?site sdk:hasSpatialCoordinates ?coords .
  ?coords sdk:hasLatitudeValue ?lat .
  FILTER(xsd:float(?lat) > 40.0)
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?manufacturer ?label ?lon WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:organizationLocatedIn ?site .
  OPTIONAL { ?manufacturer rdfs:label ?label. }
  ?site sdk:hasSpatialCoordinates ?coords .
  ?coords sdk:hasLongitudeValue ?lon .
  FILTER(xsd:float(?lon) < 90.0)
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX iof-scro: <https://spec.industrialontologies.org/ontology/supplychain/SupplyChain/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?name WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?name ;
                sdk:organizationLocatedIn ?site .
  ?site sdk:hasSpatialCoordinates ?coords .
  ?coords sdk:hasLatitudeValue ?lat ;
          sdk:hasLongitudeValue ?long .
  FILTER(?lat = "33.364638"^^xsd:float && ?long = "-111.931604"^^xsd:float)
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?cityName ?zip WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL {
    ?manufacturer sdk:organizationLocatedIn ?site .
    OPTIONAL {
      ?site sdk:locatedInCity ?city .
      ?city rdfs:label ?cityName .
    }
    OPTIONAL {
      ?site sdk:hasZIPcode ?zipNode .
      ?zipNode sdk:hasIntegerValue ?zip .
    }
  }
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?manufacturerLabel ?state ?stateLabel WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?manufacturerLabel ;
                sdk:organizationLocatedIn ?site .
  ?site sdk:locatedInCity ?city .
  ?city sdk:locatedInState ?state .
  ?state rdfs:label ?stateLabel .
  FILTER(regex(?stateLabel, "^New "))
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?company ?companyLabel ?city ?cityLabel WHERE {
  ?company a iof-core:Manufacturer ;
           rdfs:label ?companyLabel ;
           sdk:organizationLocatedIn ?site .
  ?site sdk:locatedInCity ?city .
  ?city rdfs:label ?cityLabel .
  FILTER(str(?cityLabel) = "New York")
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?stateLabel ?manu ?manuLabel ?employees WHERE {
  {
    SELECT ?manu ?state ?employees (COUNT(?other) AS ?numBetter) WHERE {
      ?manu a iof-core:Manufacturer ;
             sdk:hasNumberOfEmployees ?employees ;
             sdk:organizationLocatedIn ?site .
      ?site sdk:locatedInCity ?city .
      ?city sdk:locatedInState ?state .

      ?other a iof-core:Manufacturer ;
             sdk:hasNumberOfEmployees ?otherEmp ;
             sdk:organizationLocatedIn ?otherSite .
      ?otherSite sdk:locatedInCity ?otherCity .
      ?otherCity sdk:locatedInState ?state .

      FILTER (
        (xsd:integer(?otherEmp) > xsd:integer(?employees))
        || (xsd:integer(?otherEmp) = xsd:integer(?employees) && str(?other) < str(?manu))
      )
    } GROUP BY ?manu ?state ?employees
  }
  ?state rdfs:label ?stateLabel .
  OPTIONAL { ?manu rdfs:label ?manuLabel. }
  FILTER(?numBetter < 3)
}
ORDER BY ?stateLabel DESC(xsd:integer(?employees))

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?industry ?industryLabel ?manuf ?manufLabel ?num ?avgNum
WHERE {
  {
    SELECT ?industry (AVG(xsd:double(?employees)) AS ?avgNum)
    WHERE {
      ?m a iof-core:Manufacturer ;
         sdk:suppliesToIndustry ?industry ;
         sdk:hasNumberOfEmployees ?employees .
    }
    GROUP BY ?industry
  }
  ?manuf a iof-core:Manufacturer ;
         sdk:suppliesToIndustry ?industry ;
         sdk:hasNumberOfEmployees ?num .
  FILTER(xsd:double(?num) > ?avgNum)
  OPTIONAL { ?industry rdfs:label ?industryLabel }
  OPTIONAL { ?manuf rdfs:label ?manufLabel }
}
ORDER BY ?industry ?manufLabel

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?label (IF(EXISTS { ?manufacturer sdk:hasCertificate ?cert . ?cert a sdk:ISO9001 }, "true", "false") AS ?hasISO9001)
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL { ?manufacturer rdfs:label ?label. }
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?manufacturerLabel WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:hasProcessCapability ?cap .
  ?cap a sdk:CoatingCapability .
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel. }
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?label ?numCerts WHERE {
  {
    SELECT ?manufacturer (COUNT(?cert) AS ?numCerts) WHERE {
      ?manufacturer a iof-core:Manufacturer .
      OPTIONAL { ?manufacturer sdk:hasCertificate ?cert. }
    } GROUP BY ?manufacturer
  }
  {
    SELECT (AVG(?n) AS ?avg) WHERE {
      {
        SELECT ?m (COUNT(?c) AS ?n) WHERE {
          ?m a iof-core:Manufacturer .
          OPTIONAL { ?m sdk:hasCertificate ?c. }
        } GROUP BY ?m
      }
    }
  }
  FILTER(?numCerts > ?avg)
  OPTIONAL { ?manufacturer rdfs:label ?label. }
}
ORDER BY DESC(?numCerts)

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX iof-scro: <https://spec.industrialontologies.org/ontology/supplychain/SupplyChain/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?naics ?naicsCode ?naicsText ?state ?stateLabel ?count WHERE {
  {
    SELECT ?naics ?state (COUNT(DISTINCT ?m) AS ?count) WHERE {
      ?m a iof-core:Manufacturer ;
         sdk:hasPrimaryNAICSClassifier ?naics ;
         sdk:organizationLocatedIn ?site .
      ?site sdk:locatedInCity ?city .
      ?city sdk:locatedInState ?state .
    } GROUP BY ?naics ?state
  }
  OPTIONAL { ?naics sdk:hasNAICSCodeValue ?naicsCode . }
  OPTIONAL { ?naics sdk:hasNAICSTextValue ?naicsText . }
  OPTIONAL { ?state rdfs:label ?stateLabel . }

  {
    SELECT ?naics ?state ?count (COUNT(?b_state) AS ?numHigher) WHERE {
      {
        SELECT ?naics ?state (COUNT(DISTINCT ?m) AS ?count) WHERE {
          ?m a iof-core:Manufacturer ;
             sdk:hasPrimaryNAICSClassifier ?naics ;
             sdk:organizationLocatedIn ?site .
          ?site sdk:locatedInCity ?city .
          ?city sdk:locatedInState ?state .
        } GROUP BY ?naics ?state
      }
      {
        SELECT ?naics ?b_state (COUNT(DISTINCT ?m2) AS ?bcount) WHERE {
          ?m2 a iof-core:Manufacturer ;
              sdk:hasPrimaryNAICSClassifier ?naics ;
              sdk:organizationLocatedIn ?site2 .
          ?site2 sdk:locatedInCity ?city2 .
          ?city2 sdk:locatedInState ?b_state .
        } GROUP BY ?naics ?b_state
      }
      FILTER( ?bcount > ?count || (?bcount = ?count && str(?b_state) < str(?state)) )
    } GROUP BY ?naics ?state ?count
  }
  FILTER(?numHigher < 5)
}
ORDER BY ?naics DESC(?count)

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX iof-scro: <https://spec.industrialontologies.org/ontology/supplychain/SupplyChain/>

SELECT ?org
       (COALESCE(STR(?label), "Unknown") AS ?labelOrUnknown)
       (COALESCE(STR(?numEmp), "Unknown") AS ?numEmployeesOrUnknown)
       (COALESCE(STR(?descText), "Unknown") AS ?descriptionOrUnknown)
       (IF(STRLEN(COALESCE(GROUP_CONCAT(DISTINCT ?procLabel; separator=", "), "")) > 0,
           GROUP_CONCAT(DISTINCT ?procLabel; separator=", "),
           "Unknown") AS ?processCapabilities)
       (IF(STRLEN(COALESCE(GROUP_CONCAT(DISTINCT ?matLabel; separator=", "), "")) > 0,
           GROUP_CONCAT(DISTINCT ?matLabel; separator=", "),
           "Unknown") AS ?materialCapabilities)
WHERE {
  ?org a iof-core:Manufacturer .
  OPTIONAL { ?org rdfs:label ?label. }
  OPTIONAL { ?org sdk:hasNumberOfEmployees ?numEmp. }
  OPTIONAL { ?org iof-core:describedBy ?desc . ?desc iof-scro:hasTextValue ?descText. }
  OPTIONAL { ?org sdk:hasProcessCapability ?procCap . ?procCap rdfs:label ?procLabel. }
  OPTIONAL { ?org sdk:hasMaterialCapability ?matCap . ?matCap rdfs:label ?matLabel. }
}
GROUP BY ?org ?label ?numEmp ?descText

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?manufacturerLabel WHERE {
