  ?manufacturer sdk:suppliesToIndustry ?industry .
  ?industry a ?itype .
  FILTER(?itype IN (sdk:RenewableEnergyIndustry, sdk:UtilitiesIndustry))
  FILTER NOT EXISTS {
    ?manufacturer sdk:suppliesToIndustry ?otherIndustry .
    FILTER NOT EXISTS { ?otherIndustry a sdk:RenewableEnergyIndustry . }
    FILTER NOT EXISTS { ?otherIndustry a sdk:UtilitiesIndustry . }
  }
  OPTIONAL { ?manufacturer rdfs:label ?label }
}
GROUP BY ?manufacturer ?label
HAVING (COUNT(DISTINCT ?industry) = 2)

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?company ?companyLabel ?productCount WHERE {
  {
    SELECT ?company (COUNT(DISTINCT ?product) AS ?productCount)
    WHERE {
      ?company a iof-core:Manufacturer ;
               sdk:manufactures ?product .
    }
    GROUP BY ?company
  }
  {
    SELECT (MAX(?c) AS ?maxCount)
    WHERE {
      {
        SELECT ?comp2 (COUNT(DISTINCT ?prod2) AS ?c)
        WHERE {
          ?comp2 a iof-core:Manufacturer ;
                 sdk:manufactures ?prod2 .
        }
        GROUP BY ?comp2
      }
    }
  }
  FILTER(?productCount = ?maxCount)
  OPTIONAL { ?company rdfs:label ?companyLabel. }
}
ORDER BY ?companyLabel

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?industryType ?count WHERE {
