PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?label WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?label ;
                sdk:hasMaterialCapability ?mc .
  ?mc a ?mctype .
  FILTER (?mctype IN (sdk:UrethaneProcessingCapability, sdk:StainlessSteelProcessingCapability, sdk:BronzeProcessingCapability))

  FILTER NOT EXISTS {
    ?manufacturer sdk:hasMaterialCapability ?otherMc .
    ?otherMc a ?otherType .
    FILTER (?otherType NOT IN (sdk:UrethaneProcessingCapability, sdk:StainlessSteelProcessingCapability, sdk:BronzeProcessingCapability))
  }
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?label ?site
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:organizationLocatedIn ?site .
  OPTIONAL { ?manufacturer rdfs:label ?label. }
  OPTIONAL {
    ?site sdk:hasSpatialCoordinates ?coords .
    OPTIONAL { ?coords sdk:hasLatitudeValue ?lat. }
    OPTIONAL { ?coords sdk:hasLongitudeValue ?long. }
  }
  FILTER( !bound(?lat) || !bound(?long) )
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?label (COUNT(DISTINCT ?cert) AS ?certCount)
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL { ?manufacturer rdfs:label ?label. }
  ?manufacturer sdk:hasCertificate ?cert .
  FILTER NOT EXISTS { ?manufacturer sdk:manufactures ?prod. }
}
GROUP BY ?manufacturer ?label
HAVING (COUNT(DISTINCT ?cert) >= 1)

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-scro: <https://spec.industrialontologies.org/ontology/supplychain/SupplyChain/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?name ?descText WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL { ?manufacturer rdfs:label ?name. }
  OPTIONAL {
    ?manufacturer iof-core:describedBy ?desc .
    OPTIONAL { ?desc iof-scro:hasTextValue ?descText. }
  }
  FILTER (
    !BOUND(?desc)
    || !BOUND(?descText)
    || regex(str(?descText), "^\\s*$")
  )
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?label
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL { ?manufacturer rdfs:label ?label . }
  FILTER NOT EXISTS { ?manufacturer sdk:suppliesToIndustry ?industry . }
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?label ?count WHERE {
  {
    SELECT (AVG(?cnt) AS ?avgCert) WHERE {
      SELECT ?m (COUNT(?cert) AS ?cnt) WHERE {
        ?m a iof-core:Manufacturer .
        OPTIONAL { ?m sdk:hasCertificate ?cert . }
      } GROUP BY ?m
    }
  }
  {
    SELECT ?manufacturer (COUNT(?cert2) AS ?count) WHERE {
      ?manufacturer a iof-core:Manufacturer .
      OPTIONAL { ?manufacturer sdk:hasCertificate ?cert2 . }
    } GROUP BY ?manufacturer
  }
  OPTIONAL { ?manufacturer rdfs:label ?label }
  FILTER(?count > ?avgCert)
}
ORDER BY DESC(?count)

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?industry ?industryLabel ?manufacturer ?manufacturerLabel ?employees ?avgEmployees
WHERE {
  {
    SELECT ?industry (AVG(?empNum) AS ?avgEmployees)
    WHERE {
      ?m a iof-core:Manufacturer ;
         sdk:suppliesToIndustry ?industry ;
         sdk:hasNumberOfEmployees ?emp .
      BIND(xsd:integer(REPLACE(STR(?emp), ",", "")) AS ?empNum)
    }
    GROUP BY ?industry
  }
  ?manufacturer a iof-core:Manufacturer ;
                sdk:suppliesToIndustry ?industry ;
                sdk:hasNumberOfEmployees ?employees .
  BIND(xsd:integer(REPLACE(STR(?employees), ",", "")) AS ?empInt)
  FILTER(?empInt > ?avgEmployees)
  OPTIONAL { ?industry rdfs:label ?industryLabel }
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel }
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?stateLabel (AVG(xsd:decimal(REPLACE(str(?employees), ",", ""))) AS ?avgEmployees)
WHERE {
  {
    SELECT DISTINCT ?m ?stateLabel ?employees WHERE {
      ?m a iof-core:Manufacturer ;
         sdk:hasNumberOfEmployees ?employees ;
         sdk:organizationLocatedIn ?site ;
         sdk:manufactures ?product .
      ?product rdfs:label ?productLabel .
      FILTER(regex(str(?productLabel), "\\d"))
      ?site sdk:locatedInState ?state .
      ?state rdfs:label ?stateLabel .
    }
  }
}
GROUP BY ?stateLabel
ORDER BY ?stateLabel

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?state ?stateLabel (COUNT(DISTINCT ?procCap) AS ?totalProcessCapabilities) (COUNT(DISTINCT ?matCap) AS ?totalMaterialCapabilities)
WHERE {
  ?m a iof-core:Manufacturer ;
     sdk:organizationLocatedIn ?site .
  ?site sdk:locatedInCity ?city .
  ?city sdk:locatedInState ?state .
  OPTIONAL { ?m sdk:hasProcessCapability ?procCap }
  OPTIONAL { ?m sdk:hasMaterialCapability ?matCap }
  OPTIONAL { ?state rdfs:label ?stateLabel }
}
GROUP BY ?state ?stateLabel
ORDER BY ?stateLabel

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?naicsCodeValue ?naicsText
       (COUNT(DISTINCT ?manu) AS ?manufacturerCount)
       (COUNT(DISTINCT ?product) AS ?totalProducts)
       (AVG(DISTINCT ?employees) AS ?avgEmployees)
WHERE {
  ?manu a iof-core:Manufacturer ;
        sdk:hasPrimaryNAICSClassifier ?naics ;
        sdk:hasNumberOfEmployees ?empRaw .
  OPTIONAL { ?manu sdk:manufactures ?product. }
  ?naics sdk:hasNAICSCodeValue ?naicsCodeValue ;
         sdk:hasNAICSTextValue ?naicsText .
  BIND(xsd:decimal(?empRaw) AS ?employees)
}
GROUP BY ?naicsCodeValue ?naicsText
ORDER BY ?naicsCodeValue

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?company ?name WHERE {
  ?company a iof-core:Manufacturer ;
           rdfs:label ?name .
  FILTER ( langMatches(lang(?name), "en") || lang(?name) = "" )
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
