PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?manufacturerLabel ?product ?productLabel WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:manufactures ?product .
  ?product rdfs:label ?productLabel .
  FILTER( ?productLabel = "Tube Bending" || ?productLabel = "Punching" )
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel }
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?org ?orgLabel ?employees ?proc ?procLabel WHERE {
  ?org rdfs:label ?orgLabel ;
       sdk:hasNumberOfEmployees ?employees ;
       sdk:organizationLocatedIn ?site ;
       sdk:hasProcessCapability ?proc .
  ?site sdk:locatedInCity ?city .
  ?city sdk:locatedInState ?state .
  ?state rdfs:label ?stateLabel .
  ?proc rdfs:label ?procLabel .

  FILTER(str(?stateLabel) = "California")
  FILTER(xsd:integer(?employees) >= 20)
  FILTER(regex(str(?procLabel), "ing$", "i"))
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX iof-scro: <https://spec.industrialontologies.org/ontology/supplychain/SupplyChain/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX bfo: <http://purl.obolibrary.org/obo/>

SELECT DISTINCT ?org ?orgLabel WHERE {
  ?org a iof-core:Manufacturer ;
       rdfs:label ?orgLabel ;
       sdk:suppliesToIndustry ?ind1 , ?ind2 ;
       sdk:hasCertificate ?cert .
  ?ind1 a sdk:RenewableEnergyIndustry .
  ?ind2 a sdk:UtilitiesIndustry .
  ?cert a sdk:ISO9001 .
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX iof-scro: <https://spec.industrialontologies.org/ontology/supplychain/SupplyChain/>

SELECT ?cityLabel (AVG(?empVal) AS ?avgEmployees)
WHERE {
  {
    SELECT ?m ?city ?cityLabel ?empVal (COUNT(DISTINCT ?cap) AS ?capCount)
    WHERE {
      ?m a iof-core:Manufacturer ;
         sdk:organizationLocatedIn ?site ;
         sdk:hasNumberOfEmployees ?empRaw .
      ?site sdk:locatedInCity ?city .
      OPTIONAL {
        { ?m sdk:hasProcessCapability ?cap }
        UNION
        { ?m sdk:hasMaterialCapability ?cap }
      }
      ?city rdfs:label ?cityLabel .
      BIND(xsd:integer(?empRaw) AS ?empVal)
    }
    GROUP BY ?m ?city ?cityLabel ?empVal
    HAVING (?capCount >= 4)
  }
}
GROUP BY ?cityLabel

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?label
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL { ?manufacturer sdk:manufactures ?product . }
  OPTIONAL { ?manufacturer sdk:hasProcessCapability ?procCap . }
  OPTIONAL { ?manufacturer sdk:hasMaterialCapability ?matCap . }
  OPTIONAL { ?manufacturer rdfs:label ?label . }
}
GROUP BY ?manufacturer ?label
HAVING (
  (COUNT(DISTINCT ?product) = 2)
  ||
  (COUNT(DISTINCT ?procCap) = 2 && COUNT(DISTINCT ?matCap) = 2)
)
